def run(context):
    risk_flags = []
    for entry in context:
        if entry['stage'] in ['4A', '4B'] and entry['stage_score'] < 50:
            risk_flags.append({'symbol': entry['symbol'], 'risk_flag': 'High Risk'})
        else:
            risk_flags.append({'symbol': entry['symbol'], 'risk_flag': 'Normal'})
    return risk_flags
